-- The shop's tables, first version (lessons 25-27). Lesson 28 adds the rules (CHECK, UNIQUE, indexes).
-- "GENERATED BY DEFAULT AS IDENTITY" means: the database numbers new rows 1, 2, 3 ... for us.

CREATE TABLE product (
    id            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          VARCHAR(60)   NOT NULL UNIQUE,
    price         DECIMAL(10,2) NOT NULL,
    reorder_level INT           NOT NULL,
    quantity      INT           NOT NULL
);

CREATE TABLE customer (
    id    INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name  VARCHAR(60) NOT NULL,
    phone VARCHAR(20) NOT NULL
);

-- customer_id may be empty (NULL): that is the walk-in customer, who gives no name.
CREATE TABLE sale (
    id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id INT REFERENCES customer (id),
    sold_at     TIMESTAMP   NOT NULL,
    discount    VARCHAR(20) NOT NULL,
    payment     VARCHAR(10) NOT NULL
);

-- One row per product on a receipt. It copies unit_price, so a later price change does not rewrite history.
CREATE TABLE sale_line (
    id         INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sale_id    INT           NOT NULL REFERENCES sale (id),
    product_id INT           NOT NULL REFERENCES product (id),
    unit_price DECIMAL(10,2) NOT NULL,
    quantity   INT           NOT NULL
);

-- The stock log: every unit that came in (RECEIVED) or went out (SOLD).
CREATE TABLE stock_movement (
    id         INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id INT         NOT NULL REFERENCES product (id),
    type       VARCHAR(10) NOT NULL,
    quantity   INT         NOT NULL,
    moved_at   TIMESTAMP   NOT NULL
);
